import{_ as a,o as i,c as o,ae as n}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"Capítulo 4: Implementación y Desarrollo","description":"","frontmatter":{},"headers":[],"relativePath":"tfm/04_implementacion.md","filePath":"tfm/04_implementacion.md"}'),s={name:"tfm/04_implementacion.md"};function t(r,e,l,d,c,m){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="capitulo-4-implementacion-y-desarrollo" tabindex="-1">Capítulo 4: Implementación y Desarrollo <a class="header-anchor" href="#capitulo-4-implementacion-y-desarrollo" aria-label="Permalink to &quot;Capítulo 4: Implementación y Desarrollo&quot;">​</a></h1><h2 id="_4-1-analisis-de-requisitos-y-modelado" tabindex="-1">4.1. Análisis de Requisitos y Modelado <a class="header-anchor" href="#_4-1-analisis-de-requisitos-y-modelado" aria-label="Permalink to &quot;4.1. Análisis de Requisitos y Modelado&quot;">​</a></h2><p>Se ha formalizado el análisis funcional mediante diagramas UML, detallando los casos de uso principales (Gestión de Licitaciones, Validación de Propuestas) en el documento <code>docs/standards/requirements_UML.md</code>.</p><h2 id="_4-2-pipeline-de-desarrollo-y-seguridad-devsecops" tabindex="-1">4.2. Pipeline de Desarrollo y Seguridad (DevSecOps) <a class="header-anchor" href="#_4-2-pipeline-de-desarrollo-y-seguridad-devsecops" aria-label="Permalink to &quot;4.2. Pipeline de Desarrollo y Seguridad (DevSecOps)&quot;">​</a></h2><p>La implementación integra controles de calidad automatizados:</p><ul><li><strong>Pre-Commit (Husky)</strong>: Ejecuta <code>lint</code> y <code>test</code> para asegurar la calidad del código.</li><li><strong>Pre-Push (Husky)</strong>: <ul><li>Ejecuta <code>snyk test</code> para prevenir la subida de dependencias vulnerables.</li><li>Ejecuta <code>npm run test:coverage</code> para imponer el estándar <strong>71/60/0</strong> (71% Core Branch, 60% Global).</li></ul></li><li><strong>Observabilidad</strong>: Instrumentación con Sentry en capas Frontend y Backend.</li><li><strong>Frontend</strong>: React + Vite + TailwindCSS (Interfaz completamente localizada al <strong>Español</strong>). <ul><li><strong>Accesibilidad</strong>: Cumplimiento WCAG 2.1 AA (Navegación por teclado, anillos de foco visibles, tamaño de texto legible en móvil).</li><li><strong>Seguridad</strong>: Prevención de enumeración de usuarios mediante mensajes de error genéricos en formularios de autenticación.</li><li><strong>Autenticación en Nube</strong>: Integración con <strong>Google Sign-In</strong> (OIDC) y flujos de recuperación de contraseña (&quot;Forgot Password&quot;).</li></ul></li><li><strong>Backend</strong>: Node.js + Express + TypeScript (API REST).</li><li><strong>IA</strong>: Google Genkit (Gemini 2.5 Flash) con <strong>búsqueda vectorial</strong> (<code>gemini-embedding-001</code>, 3072 dimensiones).</li><li><strong>Base de Datos</strong>: Persistencia relacional mediante <strong>SQLite</strong> (<code>better-sqlite3</code>) con almacenamiento de <strong>embeddings vectoriales</strong> (BLOB), garantizando que los análisis no se pierdan al cerrar la sesión.</li></ul><h2 id="_4-3-implementacion-de-algoritmos-code-snippets" tabindex="-1">4.3. Implementación de Algoritmos (Code Snippets) <a class="header-anchor" href="#_4-3-implementacion-de-algoritmos-code-snippets" aria-label="Permalink to &quot;4.3. Implementación de Algoritmos (Code Snippets)&quot;">​</a></h2><p>A continuación se detallan los algoritmos clave implementados en <code>backend/src/domain</code>:</p><h3 id="_4-2-2-sistema-de-autenticacion-y-persistencia" tabindex="-1">4.2.2. Sistema de Autenticación y Persistencia <a class="header-anchor" href="#_4-2-2-sistema-de-autenticacion-y-persistencia" aria-label="Permalink to &quot;4.2.2. Sistema de Autenticación y Persistencia&quot;">​</a></h3><p>Se ha implementado un sistema robusto para la gestión de datos.</p><ul><li><strong>Autenticación</strong>: Basada en <strong>JWT (JSON Web Tokens)</strong> gestionados mediante <strong>HttpOnly Cookies</strong> (invisible para JavaScript) para mitigar ataques XSS.</li><li><strong>Persistencia de Licitaciones</strong>: Implementación del patrón <em>Repository</em> con <strong>Turso (LibSQL)</strong> para almacenar la relación entre Usuarios, Análisis, Requisitos y Resultados de Validación. Esta migración a la nube permite que los datos sobrevivan al reinicio de los contenedores de aplicación.</li><li><strong>Migración a la Nube</strong>: Pivotaje arquitectónico desde SQLite local a Turso para resolver problemas de persistencia en entornos serverless (Render).</li></ul><p><strong>Desafío Técnico: Aislamiento Cross-Origin (COOP)</strong> Durante la integración de Google Sign-In en producción, se identificó un conflicto crítico con las políticas de seguridad <code>Cross-Origin-Opener-Policy</code> (COOP). Los navegadores modernos bloqueaban la comunicación entre la aplicación (React) y la ventana emergente (Popup) de Google. <em>Solución</em>: Se implementó un cambio de estrategia hacia el flujo <code>redirect</code> (v1.1.0). En lugar de depender de ventanas secundarias, la aplicación realiza una navegación completa al proveedor de identidad y recupera el token del fragmento URL (<code>#access_token</code>) al retornar, garantizando la compatibilidad universal sin comprometer la seguridad.</p><h3 id="_4-2-3-refinamiento-de-la-logica-de-ia-fases-6-y-7" tabindex="-1">4.2.3 Refinamiento de la Lógica de IA (Fases 6 y 7) <a class="header-anchor" href="#_4-2-3-refinamiento-de-la-logica-de-ia-fases-6-y-7" aria-label="Permalink to &quot;4.2.3 Refinamiento de la Lógica de IA (Fases 6 y 7)&quot;">​</a></h3><p>Se implementó una estrategia de &quot;Doble Prompt&quot; para maximizar la precisión:</p><ol><li><strong>Extracción (Input)</strong>: Se utiliza un prompt de &quot;Auditor Legal&quot; que filtra estrictamente los requisitos obligatorios (RTOs) basándose en imperativos legales.</li><li><strong>Validación (RAG)</strong>: Se emplea un prompt de &quot;Evaluador Senior&quot; con una ventana de contexto ampliada a <strong>500,000 caracteres</strong> (Gemini 2.5 Flash), permitiendo la detección de evidencia en documentos extensos sin alucinaciones.</li><li><strong>Embeddings Cloud</strong>: Se migró el servicio de búsqueda vectorial a <strong>Google <code>gemini-embedding-001</code> (3072D)</strong>, eliminando la dependencia de servidores locales (Ollama) para el despliegue en producción.</li><li><strong>Observabilidad con LangSmith</strong>: Se integró el SDK de <strong>LangSmith</strong> para monitorizar y depurar las interacciones con la IA en tiempo real. Mediante la instrumentación de métodos clave con <code>traceable</code>, se pudieron optimizar los prompts de validación analizando casos de borde en documentos reales, garantizando que requisitos numéricos (años de experiencia, importes de seguros) sean detectados con precisión.</li></ol><h2 id="_4-3-despliegue-y-arquitectura-cloud-render-turso-gemini" tabindex="-1">4.3. Despliegue y Arquitectura Cloud (Render + Turso + Gemini) <a class="header-anchor" href="#_4-3-despliegue-y-arquitectura-cloud-render-turso-gemini" aria-label="Permalink to &quot;4.3. Despliegue y Arquitectura Cloud (Render + Turso + Gemini)&quot;">​</a></h2><p>El sistema ha evolucionado hacia un modelo <em>Cloud-Native</em> para garantizar escalabilidad y estabilidad:</p><ul><li><strong>Hosting (Render)</strong>: <ul><li><strong>Backend</strong>: Desplegado como &quot;Web Service&quot; en Node.js 22.</li><li><strong>Frontend</strong>: Desplegado como &quot;Static Site&quot; (SPA).</li><li><strong>Comunicación</strong>: Variables de entorno seguras (<code>DATA_API_KEY</code>, <code>ALLOWED_ORIGINS</code>).</li><li><strong>Mejoras UI (Fase 7.1)</strong>: Refinamiento tipográfico con fuentes Serif (<em>Playfair Display</em>) para headers y rediseño dinámico de componentes para soportar resúmenes generados por IA de longitud variable (hasta 500 caracteres).</li><li><strong>Seguridad CORS (Fase 7.2)</strong>: Implementación de lista blanca dinámica (<code>ALLOWED_ORIGINS</code>) en backend para restringir acceso exclusivamente a dominios de confianza (Producción + Localhost), mitigando riesgos de CSRF.</li><li><strong>Experiencia Móvil (Fase 7.3)</strong>: Implementación de menú de navegación responsivo (&quot;Hamburger Menu&quot;) y mejora del contraste en formularios de autenticación (<code>bg-zinc-900</code>) para garantizar la legibilidad en dispositivos pequeños.</li></ul></li><li><strong>Base de Datos (Turso)</strong>: <ul><li>Base de datos distribuida basada en libSQL.</li><li>Gestión de esquemas automática al inicio (<code>SqliteDatabase.initializeSchema()</code>).</li><li><strong>Estabilidad</strong>: Uso forzado de protocolo <code>https://</code> para evitar desconexiones en entornos serverless.</li></ul></li><li><strong>IA (Gemini 2.5 Flash)</strong>: <ul><li>Sustitución de Ollama (ejecución local pesada) por API de Google Vertex AI.</li><li>Reducción drástica de latencia (&lt;5s vs 2min) y eliminación de timeouts en despliegue.</li></ul></li></ul><h2 id="_4-4-procesamiento-de-ofertas-y-resumen-de-cumplimiento" tabindex="-1">4.4. Procesamiento de Ofertas y Resumen de Cumplimiento <a class="header-anchor" href="#_4-4-procesamiento-de-ofertas-y-resumen-de-cumplimiento" aria-label="Permalink to &quot;4.4. Procesamiento de Ofertas y Resumen de Cumplimiento&quot;">​</a></h2><p>Tras extraer los requisitos del pliego, el sistema permite subir una oferta para su validación.</p><h3 id="_4-4-1-motor-de-comparacion-ia" tabindex="-1">4.4.1. Motor de Comparación IA <a class="header-anchor" href="#_4-4-1-motor-de-comparacion-ia" aria-label="Permalink to &quot;4.4.1. Motor de Comparación IA&quot;">​</a></h3><ul><li><strong>Entrada</strong>: Texto del requisito + Texto de la oferta.</li><li><strong>Salida</strong>: JSON con estado (CUMPLE/NO CUMPLE), razonamiento detallado y cita textual de la evidencia.</li><li><strong>Optimización</strong>: Se utiliza truncado de contexto y control de tokens para asegurar que la comparativa sea precisa y rápida.</li></ul><h3 id="_4-4-2-optimizacion-de-rendimiento" tabindex="-1">4.4.2. Optimización de Rendimiento <a class="header-anchor" href="#_4-4-2-optimizacion-de-rendimiento" aria-label="Permalink to &quot;4.4.2. Optimización de Rendimiento&quot;">​</a></h3><ul><li><strong>Procesamiento Paralelo</strong>: Validación de 3 requisitos simultáneamente (3x concurrencia).</li><li><strong>Búsqueda Vectorial</strong>: Infraestructura de embeddings con <code>gemini-embedding-001</code> (3072D) para optimizaciones de filtrado semántico.</li><li><strong>Resultados Determinísticos</strong>: Temperatura 0.0 para garantizar consistencia en las validaciones.</li><li><strong>Rendimiento</strong>: Reducción del tiempo de validación de 5+ minutos a 2-3 minutos (mejora del 50%).</li></ul><h3 id="_4-4-3-visualizacion-de-estadisticas-validationsummary" tabindex="-1">4.4.3. Visualización de Estadísticas (ValidationSummary) <a class="header-anchor" href="#_4-4-3-visualizacion-de-estadisticas-validationsummary" aria-label="Permalink to &quot;4.4.3. Visualización de Estadísticas (ValidationSummary)&quot;">​</a></h3><p>Se ha desarrollado un componente de visualización que calcula dinámicamente:</p><ul><li>Porcentaje de éxito global.</li><li>Ratio de cumplimiento de requisitos <strong>OBLIGATORIOS</strong>.</li><li>Ratio de cumplimiento de requisitos <strong>OPCIONALES</strong>.</li></ul><h2 id="_4-6-validacion-dinamica-sectorial-fase-7" tabindex="-1">4.6. Validación Dinámica Sectorial (Fase 7) <a class="header-anchor" href="#_4-6-validacion-dinamica-sectorial-fase-7" aria-label="Permalink to &quot;4.6. Validación Dinámica Sectorial (Fase 7)&quot;">​</a></h2><p>Se ha implementado un sistema de validación basado en datos que permite al motor de reglas adaptarse a diferentes sectores industriales sin modificaciones en el código fuente (ADR 022).</p><ul><li><strong>Gestión de Presets</strong>: Los criterios de validación (palabras clave positivas y exclusiones) se almacenan en la tabla <code>industry_presets</code>.</li><li><strong>Factoría de Reglas</strong>: Implementación de <code>ValidationRuleFactory</code> que carga dinámicamente las reglas de validación basándose en el sector seleccionado por el usuario, permitiendo una expansión ilimitada a nuevos ámbitos (e.g., Sanidad, Servicios Sociales).</li><li><strong>Resiliencia</strong>: Inclusión de un mecanismo de fallback que garantiza la operatividad del sistema de validación incluso ante fallos en la persistencia de datos sectoriales.</li></ul><h2 id="_4-8-sistema-de-diseno-ux-ui-fase-8" tabindex="-1">4.8. Sistema de Diseño UX/UI (Fase 8) <a class="header-anchor" href="#_4-8-sistema-de-diseno-ux-ui-fase-8" aria-label="Permalink to &quot;4.8. Sistema de Diseño UX/UI (Fase 8)&quot;">​</a></h2><p>Se ha implementado un sistema de diseño integral (&quot;TenderCheck Design System&quot;) para garantizar la usabilidad y la coherencia visual:</p><ul><li><strong>Tema Dual</strong>: Soporte completo para modo Claro (inspirado en tonos &quot;Crema&quot; y papel) y Oscuro (&quot;Charcoal&quot;).</li><li><strong>Tipografía</strong>: Jerarquía visual clara mediante el uso de <em>Playfair Display</em> para títulos y <em>Inter</em> para datos densos.</li><li><strong>Feedback Visual</strong>: Uso de micro-interacciones y estados de carga (Skeletons) para mejorar la percepción de rendimiento.</li><li><strong>Accesibilidad</strong>: Alto contraste en formularios y navegación optimizada para teclado y lectores de pantalla.</li></ul><h2 id="_4-9-resultados-obtenidos" tabindex="-1">4.9. Resultados Obtenidos <a class="header-anchor" href="#_4-9-resultados-obtenidos" aria-label="Permalink to &quot;4.9. Resultados Obtenidos&quot;">​</a></h2><p>La versión final de TenderCheck AI permite:</p><ol><li><strong>Ingesta Inteligente</strong>: Procesamiento de pliegos y ofertas atomizado.</li><li><strong>Validación Basada en Evidencias</strong>: No solo dice si cumple, sino que muestra <em>por qué</em> y <em>dónde</em> está la prueba en el documento del licitador.</li><li><strong>Auditoría Histórica</strong>: Capacidad de revisar y gestionar el cumplimiento de múltiples licitaciones de forma persistente.</li><li><strong>Entrega Profesional</strong>: Generación de documentos PDF listos para ser adjuntados a un expediente de contratación.</li></ol>',36)])])}const g=a(s,[["render",t]]);export{p as __pageData,g as default};
